crypto_script:
// ============ 方案运营商 → 大学掌 isp 参数映射（可按门户要求增删改） ============
// 门户取值（原仓库 README 记载）：local / wcmcc(移动) / unicom(联通) / wtelecom(电信)，
// 默认 local（校园账号）。映射不到的取值一律落回 local。
var ISP_MAP = {
  "移动": "wcmcc",
  "联通": "unicom",
  "电信": "wtelecom"
};

// 表单体是 x-www-form-urlencoded，而模板替换不做转义：密码里出现 & = #
// 就会截断表单，故这里先做一次 URL 编码
function transform(ctx) {
  return {
    form_username: url_encode(ctx.username || ""),
    form_password: url_encode(ctx.password || ""),
    isp_value: ISP_MAP[(ctx.isp || "").trim()] || "local",
  };
}
